// NewServer so a server that never captures never allocates one, matching how `scanner` is built.
func (s *Server) captureSet() *sequencerCaptures {
	s.captureOnce.Do(func() { s.captures = newSequencerCaptures() })
	return s.captures
}

// ---- routes ------------------------------------------------------------------------------------

type sequencerCaptureReq struct {
	Target   string        `json:"target"`
	Protocol string        `json:"protocol"`
	Request  string        `json:"request"`
	Count    int           `json:"count"`
	Location tokenLocation `json:"location"`
	// DelayMs paces the loop. Sequencer captures are the one tool that deliberately hammers a single
	// endpoint, and an operator who needs to stay under a rate limit has no other way to ask.
	DelayMs int `json:"delay_ms"`
	// LengthDeviates is Burp's "Ignore token whose length deviates by X characters"
	// (settings/tools/sequencer.html): when set with Enable, tokens whose length differs from
	// the running average by more than X are dropped from the sample and counted as gated.
	// Useful when the application occasionally returns a different item where the token lives —
	// an error page where the session id was.
	LengthDeviates struct {
		Enable bool `json:"enable"`
		Chars  int  `json:"chars"`
	} `json:"length_deviates"`
	// Threads is Burp's "Number of threads" (settings/tools/sequencer.html): the maximum number of
	// concurrent requests the capture makes. 1 (or absent) is the historical sequential capture —
	// the honest default, because concurrency changes what the capture measures: a token that
	// arrives per request is unaffected, but per-request wall-clock pacing (delay) becomes a lower
	// bound shared across the pool, and an endpoint that serialises logins server-side will show a
	// capture that looks slower without producing worse tokens. The operator opts into that.
	Threads int `json:"threads"`
}

// maxCaptureCount bounds one capture at Burp's own maximum: 20,000 is what the FIPS 140-2
// statistical battery takes a formally compliant sample of, and the page presents FIPS
// results — a live capture that could not reach the compliant size would make that claim
// unreachable no matter how long the operator let it run. The default stays far below at
// 100; the bound is a ceiling on what can be ASKED for, so a typo in the count field still
// cannot commit the tool to a million requests against an engagement target
// (burpsy-react-ui-vhs0).
const maxCaptureCount = 20000

// defaultCaptureCount is what an unspecified count means. 100 matches Burp's default sample size and
// is enough for FIPS bit-level tests to report at all.
const defaultCaptureCount = 100

// maxCaptureThreads bounds the concurrency pool. Burp's own default is a handful; a pool wider than
// the bound would out-race the view's polling and the miss-streak guard's meaning (25 misses is a
// wrong location at 1 thread and a rounding error at 500). 32 keeps a capture from opening more
// sockets than the store can absorb.
const maxCaptureThreads = 32

// handleSequencerCaptureStart serves POST /api/sequencer/capture, beginning a real capture.
func (s *Server) handleSequencerCaptureStart(w http.ResponseWriter, r *http.Request) {
	var req sequencerCaptureReq
	if err := requestJSON(w, r, nil).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}
	// Skipped is the requests never sent: a capture stopped at 40 of 200 has 160 units of work with
	// no verdict, and folding them anywhere else would let a short capture read as a complete one.
	var unsent uint64
	if c.requested > c.attempts {
		unsent = uint64(c.requested - c.attempts)
	}
	return dash.Breakdown{
		Found:   uint64(collected),
		Gated:   uint64(c.missCount),
		Skipped: unsent,
	}
}

// handleSequencerCapture serves GET /api/sequencer/capture/{id} and POST /api/sequencer/capture/stop.
func (s *Server) handleSequencerCapture(w http.ResponseWriter, r *http.Request) {
	path := strings.TrimSuffix(r.PathValue("rest"), "/")
	// The guard is per-sub-path because the two sub-paths are different kinds of operation, and one
	// guard for both would have to be the looser of the two. Stopping a capture changes state, so it
	// is POST; reading a token list does not, so it is GET. Unguarded, `GET .../stop` answered
	// {"stopped":true} — a state change reported for a request that could not have caused one.
	switch {
	case (path == "stop" || path == "pause" || path == "resume") && r.Method != http.MethodPost,
		path != "stop" && path != "pause" && path != "resume" && r.Method != http.MethodGet:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "application/json")

	if path == "stop" {
		s.stopCaptures(w)
		return
	}
	if path == "pause" || path == "resume" {
		// The most recent live capture is the one the UI is looking at; pausing by explicit id
		// would need a picker this page does not have, and Burp's pause button operates on the
		// capture in front of the operator too.
		live := s.captureSet().running()
		if len(live) == 0 {
			http.Error(w, "no capture is running, so nothing to "+path, http.StatusConflict)
			return
		}
		target := live[len(live)-1]
		want := path == "pause"
		if !target.setPaused(want) {
			http.Error(w, "the capture finished before the request landed", http.StatusConflict)
			return
		}
		views := make([]captureView, 0, len(live))
		for _, c := range live {
			views = append(views, c.view())
		}
		json.NewEncoder(w).Encode(map[string]any{
			"captured": views,
			"note":     "capture " + strconv.FormatUint(target.id, 10) + " " + path + "d",
		})
		return
	}
	if path == "" {
		// The index: every capture this process has run, so a UI that lost its capture id can find it
		// again instead of being told there is nothing.
		set := s.captureSet()
		set.mu.Lock()
		ids := append([]uint64(nil), set.order...)
		set.mu.Unlock()
		views := make([]captureView, 0, len(ids))
		for _, id := range ids {
			if c := set.get(id); c != nil {
				views = append(views, c.view())
			}
		}
		json.NewEncoder(w).Encode(map[string]any{"captures": views, "retained": maxRetainedCaptures})
		return
	}
	id, err := strconv.ParseUint(path, 10, 64)
	if err != nil {
		http.Error(w, "Invalid capture id", http.StatusBadRequest)
		return
	}
	capture := s.captureSet().get(id)
	if capture == nil {
		// 404 and a reason, rather than an empty capture. `{"total": 0, "tokens": []}` for an id that
		// never existed was the original defect: it reads as a capture that found nothing.
		http.Error(w, fmt.Sprintf("no capture %d: it was never started, or it aged out of the last %d",
			id, maxRetainedCaptures), http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(capture.view())
}

// stopCaptureResp answers /stop with what actually happened.
type stopCaptureResp struct {
	// Stopped is whether anything was signalled. False with an empty Captures list is the honest
	// answer to "stop" when nothing was running; the route used to answer true unconditionally.
	Stopped   bool          `json:"stopped"`
	Signalled int           `json:"signalled"`
	Captures  []captureView `json:"captures"`
	Note      string        `json:"note"`
}

func (s *Server) stopCaptures(w http.ResponseWriter) {
	live := s.captureSet().running()
	if len(live) == 0 {
		json.NewEncoder(w).Encode(stopCaptureResp{
			Stopped:  false,
			Captures: []captureView{},
			Note:     "no capture was running, so nothing was stopped",
		})
		return
	}
	// Cancelled through the task registry rather than by touching the capture: the loop owns its own
	// state transition, and a stop that marked the capture stopped from out here would have to invent
	// the sample count it ended on.
	signalled := s.tasks.CancelKind(dash.KindSequencerCapture)
	// Give the loop a moment to notice, so the reply carries the sample it ended with rather than the
	// one it had a tick earlier. Bounded and short: this is a courtesy, not a synchronisation point,
	// and the capture's own view is authoritative either way.
	deadline := time.Now().Add(250 * time.Millisecond)
	for time.Now().Before(deadline) {
		if len(s.captureSet().running()) == 0 {
			break
		}

}

// ---- Sequencer ---------------------------------------------------------------------------------

// sequencerAnalyseReq mirrors AnalyseReq in crates/web/src/routes/sequencer.rs:
// text (one token per line), pre-split tokens, or neither — and an optional
// forced encoding. The pointer on Tokens distinguishes "absent" from "empty",
// which matters because an explicit empty array is a valid (empty) sample while
// an absent one is a caller error.
type sequencerAnalyseReq struct {
	Text     *string   `json:"text"`
	Tokens   *[]string `json:"tokens"`
	Encoding *string   `json:"encoding"`
	// SignificancePercent is the operator's significance level, as a percentage:
	// 0.03 means 0.03%, not 3%. Burp makes this the input to the whole analysis
	// ("you can choose the probability you use to interpret the randomness of
	// your findings"), and it reaches exactly one part of the report — the
	// effective-entropy curve. A pointer so an absent level is answered with the
	// default and marked as defaulted, rather than being indistinguishable from
	// an operator who typed the default.
	SignificancePercent *float64 `json:"significance_percent"`
	// Burp's "Token handling" (burpsy-react-ui-i4u). PadMode is "none" | "start" | "end"; the
	// statistical tests can only run over tokens of one length, so a variable-length sample is
	// padded up to the longest and WHERE decides which byte positions the analysis reads.
	//
	// Absent means none, which is what every existing caller means and what the analysis did before
	// this existed. An unknown value is refused by name rather than falling back to none — a
	// silently ignored pad mode would leave the operator reading an unpadded analysis believing it
	// was padded.
	PadMode *string `json:"pad_mode"`
	// PadByte is the single character to pad with. Burp's own default is '0'. A string rather than a
	// number so the wire carries what the operator typed; anything that is not exactly one byte is
	// refused, because a two-character "pad byte" cannot mean anything.
	PadByte *string `json:"pad_byte"`
	// Base64Decode is Burp's "Base64-decode before analyzing": a base64 token's randomness is in the
	// bytes it encodes, not the alphabet it is written in. A token that is not valid base64 is
	// refused by the engine naming which one, rather than analysed as a different sample.
	Base64Decode *bool `json:"base64_decode"`
	// DisabledTests is Burp's per-test switch for this one analysis (burpsy-react-ui-3iao): the
	// AnalysisTest ids to leave out, e.g. ["compression"]. A pointer so "absent" — run what the saved
	// sequencer settings leave on — is distinct from an explicit empty list, which runs every test
	// whatever the settings say. An unknown id is refused naming the accepted set: an id silently
	// ignored would leave the operator reading a verdict that still counted the test they removed.
	// "Redo analysis" is this request sent again with a different list; the report marks each
	// disabled test as not run, by name.
	DisabledTests *[]string `json:"disabled_tests"`
}

// parsePadMode maps the wire's "none" | "start" | "end" onto the engine's PadMode. Unknown values
// are refused naming the value, the same rule the encoding field follows: a pad mode that was
// silently dropped would produce an unpadded report under a padded label.
func parsePadMode(raw string) (sequencer.PadMode, error) {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "", "none":
		return sequencer.PadNone, nil
	case "start":
		return sequencer.PadStart, nil
	case "end":
		return sequencer.PadEnd, nil
	}
	return sequencer.PadNone, fmt.Errorf("pad_mode %s is not one of none, start or end", strconv.Quote(raw))
}

// parseEncoding maps the UI's "hex" | "base64" | "raw" onto the engine's
// Encoding, naming anything else rather than silently ignoring it.
func parseEncoding(name string) (sequencer.Encoding, error) {
	switch name {
	case "hex":
		return sequencer.EncodingHex, nil
	case "base64":
		return sequencer.EncodingBase64, nil
	case "raw":
		return sequencer.EncodingRaw, nil
	}
	return 0, fmt.Errorf("unknown encoding %q: expected hex, base64 or raw", name)
}

// handleSequencerAnalyse answers a pasted token list in one synchronous call —
// the Sequencer's paste mode. Takes no state at all, which is the point: pasted
// text is not traffic, so there is no scope decision to make and nothing to
// record. The response is the full SequencerReport (internal/web/ui/src/
// sequencer.ts), not the legacy aggregate shape this endpoint used to return.
func (s *Server) handleSequencerAnalyse(w http.ResponseWriter, r *http.Request) {
	var req sequencerAnalyseReq
	if err := requestJSON(w, r, nil).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}
	var tokens []string
	switch {
	case req.Tokens != nil:
		for _, t := range *req.Tokens {
			if t != "" {
				tokens = append(tokens, t)
			}
		}
	case req.Text != nil:
		tokens = sequencer.TokensFromText(*req.Text)
	default:
		http.Error(w, "no tokens: pass text (one per line) or tokens", http.StatusBadRequest)
		return
	}
	var encoding *sequencer.Encoding
	if req.Encoding != nil {
		e, err := parseEncoding(*req.Encoding)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		encoding = &e
	}
	// An empty paste is answered rather than refused: the report says "no tokens
	// were supplied", and that is more useful to whoever pasted the wrong buffer
	// than a 400 with no analysis in it.
	// Token handling, decided before the significance branch because it changes the SAMPLE rather
	// than how the sample is interpreted.
	opts := sequencer.Options{Encoding: encoding, PadByte: '0'}
	if req.PadMode != nil {
		mode, err := parsePadMode(*req.PadMode)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		opts.Pad = mode
	}
	if req.PadByte != nil {
		if len([]byte(*req.PadByte)) != 1 {
			http.Error(w, fmt.Sprintf(
				"pad_byte %s is not a single byte; padding inserts one byte per position, so a pad character must be exactly one",
				strconv.Quote(*req.PadByte)), http.StatusBadRequest)
			return
		}
		opts.PadByte = (*req.PadByte)[0]
	}
	// The saved analysis settings (burpsy-react-ui-nm81) govern whatever this request does not say for
	// itself: which tests run, and whether tokens are base64-decoded first.
	saved := s.sequencerSettings()
	opts.Base64Decode = saved.TokenHandling.Base64DecodeBeforeAnalyzing
	if req.Base64Decode != nil {
		opts.Base64Decode = *req.Base64Decode
	}
	opts.DisabledTests = saved.DisabledTests()
	if req.DisabledTests != nil {
		for _, id := range *req.DisabledTests {
			if !sequencer.KnownAnalysisTest(id) {
				http.Error(w, fmt.Sprintf("disabled_tests names %s, which is not a test this analysis runs; the tests are %s",
					strconv.Quote(id), strings.Join(sequencerTestIDs(), ", ")), http.StatusBadRequest)
				return
			}
		}
		opts.DisabledTests = append([]string(nil), *req.DisabledTests...)
	}

	w.Header().Set("Content-Type", "application/json")
	if req.SignificancePercent == nil {
		opts.SignificancePercent = sequencer.DefaultSignificancePercent
		opts.SignificanceDefaulted = true
		rep, err := sequencer.AnalyseOpts(tokens, opts)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		json.NewEncoder(w).Encode(rep)
		return
	}
	// Refused, not clamped. A level above 10% or below 0.001% is outside the
	// range Burp's analysis is defined over, and silently moving it to the edge
	// would answer a different question under the operator's number — the same
	// refusal the encoding field makes for an unknown alphabet.
	if !sequencer.ValidSignificancePercent(*req.SignificancePercent) {
		http.Error(w, fmt.Sprintf(
			"significance_percent %g is outside the range this analysis is defined over: %g to %g, as a percentage (0.03 means 0.03%%, not 3%%). Burp's own guidance puts FIPS work at 0.002%%-0.03%% and scientific work at 1%%-5%%.",
			*req.SignificancePercent, sequencer.MinSignificancePercent, sequencer.MaxSignificancePercent),
			http.StatusBadRequest)
		return
	}
	opts.SignificancePercent = *req.SignificancePercent
	rep, err := sequencer.AnalyseOpts(tokens, opts)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	json.NewEncoder(w).Encode(rep)
}

